
CREATE TABLE "public"."QuickSqlOrder" ("Id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "CustomerName" VARCHAR(64) NULL, "CustomerId" INTEGER NOT NULL, "Amount" NUMERIC(18,4) NOT NULL, "State" INTEGER NOT NULL, "CreatedAt" TIMESTAMP(3) NOT NULL, "PaidAt" TIMESTAMP(3) NULL, "Note" TEXT NULL, CONSTRAINT "PK_QuickSqlOrder" PRIMARY KEY ("Id")) ; CREATE INDEX "IX_QuickSqlOrder_CreatedAt" ON "public"."QuickSqlOrder" ( "CreatedAt" ASC )
